type Projection struct { Total,Last int }
func (p *Projection) Apply(seq,delta int) (int,error) {
    if seq<=p.Last { return p.Total,nil }
    if seq!=p.Last+1 { return 0,fmt.Errorf("gap") }
    p.Total+=delta
    p.Last=seq
    return p.Total,nil
}
func (p *Projection) Query() int { return p.Total }

import java.util.List;
interface Transport { Object get(String target,int id); }
final class Router {
    static Object get(List<String> targets,Transport transport,int id) {
        if (id<0 || targets.isEmpty()) throw new IllegalArgumentException("shard");
        int index=id%targets.size();
        return transport.get(targets.get(index),id);
    }
}

